PAGES = {'https://ornek.com/': '<html><title>Kitapçı</title></html>'}

def fake_get(url):
    if url in PAGES:
        return Response(200, PAGES[url])
    return Response(404, 'Not Found')

r = fake_get('https://ornek.com/')
print(r.status_code, r.text[:20])
