PAGES = {'/kitaplar': '<ul><li>Sefiller</li></ul>'}

def fetch(url):
    if url not in PAGES:
        raise LookupError(f'404 for {url}')
    return PAGES[url]

for url in ['/kitaplar', '/filmler']:
    try:
        print('OK', fetch(url))
    except LookupError as e:
        print('Skipped:', e)

def status_text(code):
    if 200 <= code < 300:
        return 'ok'
    elif code == 429:
        return 'wait'
    return 'error'

print([status_text(c) for c in [200, 204, 429, 404]])

