from html.parser import HTMLParser

class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.links.append(dict(attrs).get('href'))

p = LinkParser()
p.feed('<p>Bak:<br><a href="/a">A</a> <a href="/b">B</a></p>')
print(p.links)

